/*
 * A039347  Numbers whose base-8 representation has the same nonzero number of
 *          3's and 4's.
 * https://oeis.org/A039347
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 18, u16 n <= 52, u32 n <= 52, u64 n <= 52, u128 n <= 52,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Implementation: sequence A039347
 * Numbers whose base-8 representation has the same nonzero number of 3's and 4's.
 * Generated by scanning integers in ascending order and selecting those that satisfy
 * the condition. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset is 1; n=0 is undefined, return 0 */
    idx_t found = 0;
    idx_t num   = 0;

    while (found < n)
    {
        ++num;                      /* next candidate */
        idx_t tmp = num;
        int c3 = 0, c4 = 0;

        /* count 3's and 4's in base 8 (tmp > 0) */
        while (tmp)
        {
            int d = tmp & 7;         /* tmp % 8 */
            if (d == 3) ++c3;
            else if (d == 4) ++c4;
            tmp >>= 3;                /* tmp /= 8 */
        }

        if (c3 == c4 && c3 > 0)
            ++found;
    }

    return (seq_t)num;
}
